class Solution {

    /**
     * @param Integer[] $nums
     * @return Integer
     */
    function maxScore($nums) {
        $m = count($nums);
        $n = $m / 2;

        $gcd = [];
        for ($i = 0; $i < $m; $i++) {
            for ($j = $i + 1; $j < $m; $j++) {
                $a = $nums[$i];
                $b = $nums[$j];
                while ($b != 0) {
                    $t = $b;
                    $b = $a % $b;
                    $a = $t;
                }
                $gcd[$i][$j] = $a;
            }
        }

        $limit = 1 << $m;
        $dp = array_fill(0, $limit, 0);
        $popcount = array_fill(0, $limit, 0);

        for ($mask = 1; $mask < $limit; $mask++) {
            $popcount[$mask] = $popcount[$mask >> 1] + ($mask & 1);
        }

        for ($mask = 0; $mask < $limit; $mask++) {
            if (($popcount[$mask] & 1) !== 0) {
                continue;
            }

            $k = ($popcount[$mask] >> 1) + 1;
            if ($k > $n) {
                continue;
            }

            $i = 0;
            while (($mask & (1 << $i)) !== 0) {
                $i++;
            }

            for ($j = $i + 1; $j < $m; $j++) {
                if (($mask & (1 << $j)) === 0) {
                    $newMask = $mask | (1 << $i) | (1 << $j);
                    $val = $dp[$mask] + $k * $gcd[$i][$j];
                    if ($val > $dp[$newMask]) {
                        $dp[$newMask] = $val;
                    }
                }
            }
        }

        return $dp[$limit - 1];
    }
}
