class Solution {

    /**
     * @param Integer[] $nums
     * @param Integer $k
     * @return Float[]
     */
    function medianSlidingWindow($nums, $k) {
        $n = count($nums);
        $small = new SplPriorityQueue(); // Max-heap: holds smaller half
        $large = new SplPriorityQueue(); // Min-heap: holds larger half (store negated values)

        $delayed = [];
        $smallSize = 0;
        $largeSize = 0;

        $prune = function($heap, &$delayed, $isMin) {
            while (!$heap->isEmpty()) {
                $val = $heap->top();
                $actualVal = $isMin ? -$val : $val;
                if (!empty($delayed[$actualVal])) {
                    $delayed[$actualVal]--;
                    $heap->extract();
                } else {
                    break;
                }
            }
        };

        // Initialize first k elements
        for ($i = 0; $i < $k; $i++) {
            $num = $nums[$i];
            if ($small->isEmpty() || $num <= $small->top()) {
                $small->insert($num, $num);
                $smallSize++;
            } else {
                $large->insert(-$num, -$num);
                $largeSize++;
            }
        }

        // Balance initial window
        $targetSmall = (int)(($k + 1) / 2);
        while ($smallSize > $targetSmall) {
            $val = $small->extract();
            $large->insert(-$val, -$val);
            $smallSize--;
            $largeSize++;
        }
        while ($smallSize < $targetSmall) {
            $val = -$large->extract();
            $small->insert($val, $val);
            $smallSize++;
            $largeSize--;
        }

        $res = [];
        $getMedian = function() use ($small, $large, $k) {
            if ($k % 2 === 1) {
                return (float)$small->top();
            } else {
                return ($small->top() + (-$large->top())) / 2.0;
            }
        };

        $res[] = $getMedian();

        for ($i = $k; $i < $n; $i++) {
            $in = $nums[$i];
            $out = $nums[$i - $k];

            // Add $out to delayed
            $delayed[$out] = ($delayed[$out] ?? 0) + 1;

            if ($out <= $small->top()) {
                $smallSize--;
            } else {
                $largeSize--;
            }

            // Insert incoming element
            if ($small->isEmpty() || $in <= $small->top()) {
                $small->insert($in, $in);
                $smallSize++;
            } else {
                $large->insert(-$in, -$in);
                $largeSize++;
            }

            // Balance sizes: smallSize should be targetSmall
            while ($smallSize > $targetSmall) {
                $prune($small, $delayed, false);
                $val = $small->extract();
                $large->insert(-$val, -$val);
                $smallSize--;
                $largeSize++;
            }
            while ($smallSize < $targetSmall) {
                $prune($large, $delayed, true);
                $val = -$large->extract();
                $small->insert($val, $val);
                $smallSize++;
                $largeSize--;
            }

            $prune($small, $delayed, false);
            $prune($large, $delayed, true);

            $res[] = $getMedian();
        }

        return $res;
    }
}
