class Solution {

    /**
     * @param String $s
     * @return String[]
     */
    function ambiguousCoordinates($s) {
        $digits = substr($s, 1, -1);
        $n = strlen($digits);
        $result = [];

        for ($i = 1; $i < $n; $i++) {
            $leftStr = substr($digits, 0, $i);
            $rightStr = substr($digits, $i);

            $leftValid = $this->getValid($leftStr);
            $rightValid = $this->getValid($rightStr);

            foreach ($leftValid as $x) {
                foreach ($rightValid as $y) {
                    $result[] = "($x, $y)";
                }
            }
        }

        return $result;
    }

    private function getValid($sub) {
        $len = strlen($sub);
        $valid = [];

        for ($d = 1; $d <= $len; $d++) {
            $left = substr($sub, 0, $d);
            $right = substr($sub, $d);

            if ($d === $len) {
                if ($len === 1 || $sub[0] !== '0') {
                    $valid[] = $left;
                }
            } else {
                if (($d === 1 || $left[0] !== '0') && substr($right, -1) !== '0') {
                    $valid[] = $left . '.' . $right;
                }
            }
        }

        return $valid;
    }
}
