class Solution {

    /**
     * @param Integer[] $arr
     * @return Integer
     */
    function numFactoredBinaryTrees($arr) {
        $MOD = 1000000007;
        sort($arr);
        $dp = [];

        foreach ($arr as $x) {
            $dp[$x] = 1;
        }

        $n = count($arr);
        for ($i = 0; $i < $n; $i++) {
            $x = $arr[$i];
            for ($j = 0; $j < $i; $j++) {
                $left = $arr[$j];
                if ($left * $left > $x) {
                    break;
                }
                if ($x % $left === 0) {
                    $right = intdiv($x, $left);
                    if (isset($dp[$right])) {
                        $ways = ($dp[$left] * $dp[$right]) % $MOD;
                        if ($left === $right) {
                            $dp[$x] = ($dp[$x] + $ways) % $MOD;
                        } else {
                            $dp[$x] = ($dp[$x] + 2 * $ways) % $MOD;
                        }
                    }
                }
            }
        }

        $ans = 0;
        foreach ($dp as $val) {
            $ans = ($ans + $val) % $MOD;
        }

        return $ans;
    }
}
