class Solution {

    /**
     * @param Integer[] $nums
     * @return Integer
     */
    function countMaxOrSubsets($nums) {
        $max_or = 0;
        foreach ($nums as $num) {
            $max_or |= $num;
        }

        $n = count($nums);

        $dfs = function ($index, $current_or) use (&$dfs, &$nums, $max_or, $n) {
            if ($current_or === $max_or) {
                return 1 << ($n - $index);
            }
            if ($index === $n) {
                return 0;
            }
            return $dfs($index + 1, $current_or | $nums[$index]) + $dfs($index + 1, $current_or);
        };

        return $dfs(0, 0);
    }
}
