class CustomStack {
    private $maxSize;
    private $stack;
    private $inc;

    /**
     * @param Integer $maxSize
     */
    function __construct($maxSize) {
        $this->maxSize = $maxSize;
        $this->stack = [];
        $this->inc = [];
    }

    /**
     * @param Integer $x
     * @return NULL
     */
    function push($x) {
        if (count($this->stack) < $this->maxSize) {
            $this->stack[] = $x;
            $this->inc[] = 0;
        }
    }

    /**
     * @return Integer
     */
    function pop() {
        $idx = count($this->stack) - 1;
        if ($idx < 0) {
            return -1;
        }

        if ($idx > 0) {
            $this->inc[$idx - 1] += $this->inc[$idx];
        }

        $res = array_pop($this->stack) + array_pop($this->inc);
        return $res;
    }

    /**
     * @param Integer $k
     * @param Integer $val
     * @return NULL
     */
    function increment($k, $val) {
        $idx = min($k, count($this->stack)) - 1;
        if ($idx >= 0) {
            $this->inc[$idx] += $val;
        }
    }
}

