class MKAverage {
    private $m;
    private $k;
    private $MAX_VAL = 100000;
    private $bit_cnt;
    private $bit_sum;
    private $buffer;
    private $head = 0;
    private $count = 0;

    /**
     * @param Integer $m
     * @param Integer $k
     */
    function __construct($m, $k) {
        $this->m = $m;
        $this->k = $k;
        $this->bit_cnt = array_fill(0, $this->MAX_VAL + 1, 0);
        $this->bit_sum = array_fill(0, $this->MAX_VAL + 1, 0);
        $this->buffer = array_fill(0, $m, 0);
    }

    private function update($val, $delta) {
        $sum_delta = $val * $delta;
        for ($i = $val; $i <= $this->MAX_VAL; $i += $i & -$i) {
            $this->bit_cnt[$i] += $delta;
            $this->bit_sum[$i] += $sum_delta;
        }
    }

    private function query_sum($idx) {
        $s = 0;
        for ($i = $idx; $i > 0; $i -= $i & -$i) {
            $s += $this->bit_sum[$i];
        }
        return $s;
    }

    private function get_sum_of_smallest($target_k) {
        if ($target_k == 0) {
            return 0;
        }
        $idx = 0;
        $cnt = 0;
        for ($i = 65536; $i > 0; $i >>= 1) {
            if ($idx + $i <= $this->MAX_VAL && $cnt + $this->bit_cnt[$idx + $i] < $target_k) {
                $idx += $i;
                $cnt += $this->bit_cnt[$idx];
            }
        }
        $sum = $this->query_sum($idx);
        $rem = $target_k - $cnt;
        $sum += $rem * ($idx + 1);
        return $sum;
    }

    /**
     * @param Integer $num
     * @return NULL
     */
    function addElement($num) {
        if ($this->count < $this->m) {
            $this->buffer[$this->head] = $num;
            $this->head = ($this->head + 1) % $this->m;
            $this->count++;
            $this->update($num, 1);
        } else {
            $old = $this->buffer[$this->head];
            $this->update($old, -1);
            $this->buffer[$this->head] = $num;
            $this->head = ($this->head + 1) % $this->m;
            $this->update($num, 1);
        }
    }

    /**
     * @return Integer
     */
    function calculateMKAverage() {
        if ($this->count < $this->m) {
            return -1;
        }
        $sum_k = $this->get_sum_of_smallest($this->k);
        $sum_m_minus_k = $this->get_sum_of_smallest($this->m - $this->k);
        $mid_sum = $sum_m_minus_k - $sum_k;
        return intdiv($mid_sum, $this->m - 2 * $this->k);
    }
}
