     */
    function canCross($stones) {
        $n = count($stones);
        if ($stones[1] !== 1) {
            return false;
        }
        if ($n === 2) {
            return true;
        }

        $posMap = array_flip($stones);
        $dp = [];
        $dp[1][1] = true;

        for ($i = 1; $i < $n; $i++) {
