    /**
     * @param Integer[][] $grid
     * @return Integer
     */
    function largestMagicSquare($grid) {
        $m = count($grid);
        $n = count($grid[0]);

        // Precompute row prefix sums
        // rowPref[r][c] is the sum of grid[r][0..c-1]
        $rowPref = [];
        for ($r = 0; $r < $m; $r++) {
            $rowPref[$r][0] = 0;
            for ($c = 0; $c < $n; $c++) {
                $rowPref[$r][$c + 1] = $rowPref[$r][$c] + $grid[$r][$c];
            }
        }

        // Precompute column prefix sums
        // colPref[r][c] is the sum of grid[0..r-1][c]
        $colPref = [];
        for ($c = 0; $c < $n; $c++) {
            $colPref[0][$c] = 0;
        }
        for ($r = 0; $r < $m; $r++) {
            for ($c = 0; $c < $n; $c++) {
                $colPref[$r + 1][$c] = $colPref[$r][$c] + $grid[$r][$c];
            }
        }

        // Precompute main diagonal (top-left to bottom-right)
        // d1[r+1][c+1] = sum along diagonal ending at (r, c)
        $d1 = array_fill(0, $m + 2, array_fill(0, $n + 2, 0));
        for ($r = 0; $r < $m; $r++) {
            for ($c = 0; $c < $n; $c++) {
                $d1[$r + 1][$c + 1] = $d1[$r][$c] + $grid[$r][$c];
            }
        }

        // Precompute anti-diagonal (top-right to bottom-left)
        // d2[r+1][c+1] = sum along anti-diagonal ending at (r, c)
        $d2 = array_fill(0, $m + 2, array_fill(0, $n + 2, 0));
        for ($r = 0; $r < $m; $r++) {
            for ($c = 0; $c < $n; $c++) {
                $d2[$r + 1][$c + 1] = $d2[$r][$c + 2] + $grid[$r][$c];
            }
        }

        for ($k = min($m, $n); $k >= 2; $k--) {
            for ($r = 0; $r <= $m - $k; $r++) {
                for ($c = 0; $c <= $n - $k; $c++) {
                    // Main diagonal: from (r, c) to (r + k - 1, c + k - 1)
                    $diag1 = $d1[$r + $k][$c + $k] - $d1[$r][$c];

                    // Anti-diagonal: from (r, c + k - 1) to (r + k - 1, c)
                    $diag2 = $d2[$r + $k][$c + 1] - $d2[$r][$c + $k + 1];

                    if ($diag1 !== $diag2) {
                        continue;
                    }

                    $target = $diag1;
                    $valid = true;

                    // Check rows
                    for ($i = 0; $i < $k; $i++) {
                        $sum = $rowPref[$r + $i][$c + $k] - $rowPref[$r + $i][$c];
                        if ($sum !== $target) {
                            $valid = false;
                            break;
                        }
                    }

                    if (!$valid) {
                        continue;
                    }

                    // Check columns
                    for ($j = 0; $j < $k; $j++) {
                        $sum = $colPref[$r + $k][$c + $j] - $colPref[$r][$c + $j];
                        if ($sum !== $target) {
                            $valid = false;
                            break;
                        }
                    }

                    if ($valid) {
                        return $k;
                    }
                }
            }
        }

        return 1;
    }
