                    $g = $this->gcd($dx, $dy);
                    $dx = (int)($dx / $g);
                    $dy = (int)($dy / $g);
                    $slope = "$dy/$dx";
                }

                $counts[$slope] = ($counts[$slope] ?? 0) + 1;
            }

            foreach ($counts as $count) {
                if ($count + 1 > $ans) {
                    $ans = $count + 1;
