class Solution {

    /**
     * @param Integer[] $nums
     * @param Integer $numSlots
     * @return Integer
     */
    function maximumANDSum($nums, $numSlots) {
        $n = count($nums);
        $totalStates = 1;
        $powersOf3 = [1];
        for ($i = 0; $i < $numSlots; $i++) {
            $powersOf3[$i + 1] = $powersOf3[$i] * 3;
        }
        $totalStates = $powersOf3[$numSlots];

        $dp = array_fill(0, $totalStates, -1);
        $count = array_fill(0, $totalStates, 0);

        $dp[0] = 0;
        $ans = 0;

        for ($state = 0; $state < $totalStates; $state++) {
            $count[$state] = $count[intdiv($state, 3)] + ($state % 3);

            if ($dp[$state] === -1) {
                continue;
            }

            $c = $count[$state];
            if ($c === $n) {
                if ($dp[$state] > $ans) {
                    $ans = $dp[$state];
                }
                continue;
            }

            for ($s = 0; $s < $numSlots; $s++) {
                $digit = intdiv($state, $powersOf3[$s]) % 3;
                if ($digit < 2) {
                    $nextState = $state + $powersOf3[$s];
                    $val = $dp[$state] + ($nums[$c] & ($s + 1));
                    if ($val > $dp[$nextState]) {
                        $dp[$nextState] = $val;
                    }
                }
            }
        }

        return $ans;
    }
}
