class Solution {

    /**
     * @param Integer[][] $students
     * @param Integer[][] $mentors
     * @return Integer
     */
    function maxCompatibilitySum($students, $mentors) {
        $m = count($students);
        $n = count($students[0]);

        $score = array_fill(0, $m, array_fill(0, $m, 0));
        for ($i = 0; $i < $m; $i++) {
            for ($j = 0; $j < $m; $j++) {
                $s = 0;
                for ($k = 0; $k < $n; $k++) {
                    if ($students[$i][$k] === $mentors[$j][$k]) {
                        $s++;
                    }
                }
                $score[$i][$j] = $s;
            }
        }

        $limit = 1 << $m;
        $dp = array_fill(0, $limit, 0);

        for ($mask = 0; $mask < $limit; $mask++) {
            $i = 0;
            for ($temp = $mask; $temp > 0; $temp &= ($temp - 1)) {
                $i++;
            }

            if ($i >= $m) {
                continue;
            }

            for ($j = 0; $j < $m; $j++) {
                if (($mask & (1 << $j)) === 0) {
                    $nextMask = $mask | (1 << $j);
                    if ($dp[$mask] + $score[$i][$j] > $dp[$nextMask]) {
                        $dp[$nextMask] = $dp[$mask] + $score[$i][$j];
                    }
                }
            }
        }

        return $dp[$limit - 1];
    }
}
