class Solution {

    /**
     * @param Integer $n
     * @param Integer[] $batteries
     * @return Integer
     */
    function maxRunTime($n, $batteries) {
        sort($batteries);
        $sum = array_sum($batteries);
        $i = count($batteries) - 1;

        while ($batteries[$i] > intdiv($sum, $n)) {
            $sum -= $batteries[$i];
            $n--;
            $i--;
        }

        return intdiv($sum, $n);
    }
}
