     * @param String[][] $seats
     * @return Integer
     */
    function maxStudents($seats) {
        $m = count($seats);
        $n = count($seats[0]);

        $valid = [];
        for ($r = 0; $r < $m; $r++) {
            $mask = 0;
            for ($c = 0; $c < $n; $c++) {
                if ($seats[$r][$c] === '.') {
                    $mask |= (1 << $c);
                }
            }
            $valid[$r] = $mask;
        }

        $dp = [0 => 0];

        for ($r = 0; $r < $m; $r++) {
            $next_dp = [];
            $v = $valid[$r];

            // Iterate over all submasks of $v
            $sub = $v;
            while (true) {
                // Check if current mask has adjacent students
                if (($sub & ($sub >> 1)) === 0) {
                    $cnt = 0;
                    $temp = $sub;
                    while ($temp > 0) {
                        $temp &= ($temp - 1);
                        $cnt++;
                    }

                    $maxStudents = -1;
                    foreach ($dp as $prevMask => $prevCount) {
                        if (($sub & ($prevMask >> 1)) === 0 && ($sub & ($prevMask << 1)) === 0) {
                            if ($prevCount + $cnt > $maxStudents) {
                                $maxStudents = $prevCount + $cnt;
                            }
                        }
                    }

                    if ($maxStudents !== -1) {
                        $next_dp[$sub] = $maxStudents;
                    }
                }

                if ($sub === 0) {
                    break;
                }
                $sub = ($sub - 1) & $v;
            }

            $dp = $next_dp;
        }

        $ans = 0;
        foreach ($dp as $count) {
            if ($count > $ans) {
                $ans = $count;
            }
        }

        return $ans;
    }
