class Solution {

    /**
     * @param Integer[] $flowers
     * @param Integer $newFlowers
     * @param Integer $target
     * @param Integer $full
     * @param Integer $partial
     * @return Integer
     */
    function maximumBeauty($flowers, $newFlowers, $target, $full, $partial) {
        $n = count($flowers);
        for ($i = 0; $i < $n; $i++) {
            if ($flowers[$i] > $target) {
                $flowers[$i] = $target;
            }
        }
        sort($flowers);

        if ($flowers[0] >= $target) {
            return $n * $full;
        }

        // prefix sums
        $prefix = array_fill(0, $n + 1, 0);
        for ($i = 0; $i < $n; $i++) {
            $prefix[$i + 1] = $prefix[$i] + $flowers[$i];
        }

        // suffix cost to make flowers[i...n-1] equal to target
        $suffixCost = array_fill(0, $n + 1, 0);
        for ($i = $n - 1; $i >= 0; $i--) {
            $suffixCost[$i] = $suffixCost[$i + 1] + ($target - $flowers[$i]);
        }

        $ans = 0;
        $k = 0;

        // i is the start index of complete gardens suffix, so there are n - i complete gardens
        // and incomplete gardens are in range [0, i - 1] (length m = i)
        for ($i = 0; $i <= $n; $i++) {
            $costFull = $suffixCost[$i];
            if ($costFull > $newFlowers) {
                continue;
            }

            $rem = $newFlowers - $costFull;
            $completed = $n - $i;

            if ($i == 0) {
                $beauty = $completed * $full;
                if ($beauty > $ans) {
                    $ans = $beauty;
                }
                continue;
            }

            // Incomplete gardens are flowers[0 ... i - 1]
            // We advance or keep $k < i such that cost to raise [0...k] to flowers[k] <= rem
            if ($k >= $i) {
                $k = $i - 1;
            }
            while ($k + 1 < $i) {
                $nextCost = ($k + 2) * $flowers[$k + 1] - $prefix[$k + 2];
                if ($nextCost <= $rem) {
                    $k++;
                } else {
                    break;
                }
            }
            while ($k > 0) {
                $curCost = ($k + 1) * $flowers[$k] - $prefix[$k + 1];
                if ($curCost > $rem) {
                    $k--;
                } else {
                    break;
                }
            }

            $c_k = ($k + 1) * $flowers[$k] - $prefix[$k + 1];
            $extra = intdiv($rem - $c_k, $k + 1);
            $minVal = $flowers[$k] + $extra;
            if ($minVal > $target - 1) {
                $minVal = $target - 1;
            }

            $beauty = $completed * $full + $minVal * $partial;
            if ($beauty > $ans) {
                $ans = $beauty;
            }
        }

        return $ans;
    }
}
