        $n = count($graph);
        $isInitial = array_fill(0, $n, false);
        foreach ($initial as $u) {
            $isInitial[$u] = true;
        }

        // Find connected components among clean (non-initial) nodes
        $visited = array_fill(0, $n, false);
        $savedBy = array_fill(0, $n, 0);

        for ($i = 0; $i < $n; $i++) {
