            // BFS / DFS to find the component and adjacent initial nodes
            $component = [];
            $queue = [$i];
            $visited[$i] = true;

            $infectedNeighbors = [];

            $head = 0;
            while ($head < count($queue)) {
                $curr = $queue[$head++];
                $component[] = $curr;

                for ($neighbor = 0; $neighbor < $n; $neighbor++) {
                    if ($graph[$curr][$neighbor] == 1) {
                        if ($isInitial[$neighbor]) {
                            $infectedNeighbors[$neighbor] = true;
                        } else if (!$visited[$neighbor]) {
                            $visited[$neighbor] = true;
                            $queue[] = $neighbor;
