        $adj = array_fill(0, $n, []);
        foreach ($edges as $edge) {
            $u = $edge[0];
            $v = $edge[1];
            $time = $edge[2];
            $adj[$u][] = [$v, $time];
            $adj[$v][] = [$u, $time];
