        $pq = new SplPriorityQueue();
        // Priority queue ordered by min cost (using negative cost as priority)
        $pq->insert([$passingFees[0], 0, 0], -$passingFees[0]);

        while (!$pq->isEmpty()) {
            [$cost, $time, $u] = $pq->extract();

            if ($time >= $minTime[$u]) {
                continue;
            }
            $minTime[$u] = $time;

            if ($u === $n - 1) {
                return $cost;
