            foreach ($adj[$u] as [$v, $travelTime]) {
                $nextTime = $time + $travelTime;
                if ($nextTime <= $maxTime && $nextTime < $minTime[$v]) {
                    $nextCost = $cost + $passingFees[$v];
                    $pq->insert([$nextCost, $nextTime, $v], -$nextCost);
