class Solution {

    /**
     * @param Integer[] $bloomDay
     * @param Integer $m
     * @param Integer $k
     * @return Integer
     */
    function minDays($bloomDay, $m, $k) {
        $n = count($bloomDay);
        if ($m * $k > $n) {
            return -1;
        }

        $low = 1;
        $high = 0;
        foreach ($bloomDay as $day) {
            if ($day > $high) {
                $high = $day;
            }
        }

        $ans = -1;
        while ($low <= $high) {
            $mid = intdiv($low + $high, 2);
            if ($this->canMake($bloomDay, $m, $k, $mid)) {
                $ans = $mid;
                $high = $mid - 1;
            } else {
                $low = $mid + 1;
            }
        }

        return $ans;
    }

    private function canMake(&$bloomDay, $m, $k, $days) {
        $bouquets = 0;
        $flowers = 0;
        foreach ($bloomDay as $day) {
            if ($day <= $days) {
                $flowers++;
                if ($flowers == $k) {
                    $bouquets++;
                    $flowers = 0;
                }
            } else {
                $flowers = 0;
            }
        }
        return $bouquets >= $m;
    }
}
