class Solution {

    /**
     * @param Integer[] $tasks
     * @param Integer $sessionTime
     * @return Integer
     */
    function minSessions($tasks, $sessionTime) {
        $n = count($tasks);
        $totalStates = 1 << $n;
        $dp = array_fill(0, $totalStates, PHP_INT_MAX);

        // State encoded as (sessions << 5) | current_session_time
        $dp[0] = (1 << 5) | 0;

        for ($mask = 0; $mask < $totalStates; $mask++) {
            $cur = $dp[$mask];
            $s = $cur >> 5;
            $t = $cur & 31;

            for ($i = 0; $i < $n; $i++) {
                if (!($mask & (1 << $i))) {
                    $nextMask = $mask | (1 << $i);
                    if ($t + $tasks[$i] <= $sessionTime) {
                        $cand = ($s << 5) | ($t + $tasks[$i]);
                    } else {
                        $cand = (($s + 1) << 5) | $tasks[$i];
                    }

                    if ($cand < $dp[$nextMask]) {
                        $dp[$nextMask] = $cand;
                    }
                }
            }
        }

        return $dp[$totalStates - 1] >> 5;
    }
}
