class Solution {

    private $comb = [];
    private $mod = 1000000007;

    /**
     * @param Integer[] $nums
     * @return Integer
     */
    function numOfWays($nums) {
        $n = count($nums);
        $this->comb = array_fill(0, $n + 1, array_fill(0, $n + 1, 0));

        for ($i = 0; $i <= $n; $i++) {
            $this->comb[$i][0] = 1;
            for ($j = 1; $j <= $i; $j++) {
                $this->comb[$i][$j] = ($this->comb[$i - 1][$j - 1] + $this->comb[$i - 1][$j]) % $this->mod;
            }
        }

        $ans = $this->dfs($nums);
        return ($ans - 1 + $this->mod) % $this->mod;
    }

    private function dfs($nums) {
        $count = count($nums);
        if ($count <= 2) {
            return 1;
        }

        $root = $nums[0];
        $left = [];
        $right = [];

        for ($i = 1; $i < $count; $i++) {
            if ($nums[$i] < $root) {
                $left[] = $nums[$i];
            } else {
                $right[] = $nums[$i];
            }
        }

        $leftWays = $this->dfs($left);
        $rightWays = $this->dfs($right);

        $ways = ($this->comb[count($left) + count($right)][count($left)] * $leftWays) % $this->mod;
        $ways = ($ways * $rightWays) % $this->mod;

        return $ways;
    }
}
