class Solution {

    /**
     * @param Integer[] $nums1
     * @param Integer[] $nums2
     * @return Integer
     */
    function numTriplets($nums1, $nums2) {
        return $this->countWays($nums1, $nums2) + $this->countWays($nums2, $nums1);
    }

    private function countWays(&$nums1, &$nums2) {
        $arr2 = $nums2;
        sort($arr2);
        $n2 = count($arr2);

        $counts1 = array_count_values($nums1);
        $total = 0;

        foreach ($counts1 as $x => $freq) {
            $target = $x * $x;
            $pairs = 0;
            $l = 0;
            $r = $n2 - 1;

            while ($l < $r) {
                $prod = $arr2[$l] * $arr2[$r];
                if ($prod < $target) {
                    $l++;
                } elseif ($prod > $target) {
                    $r--;
                } else {
                    if ($arr2[$l] === $arr2[$r]) {
                        $count = $r - $l + 1;
                        $pairs += intdiv($count * ($count - 1), 2);
                        break;
                    } else {
                        $vl = $arr2[$l];
                        $vr = $arr2[$r];
                        $cntL = 0;
                        while ($l < $r && $arr2[$l] === $vl) {
                            $cntL++;
                            $l++;
                        }
                        $cntR = 0;
                        while ($r >= $l && $arr2[$r] === $vr) {
                            $cntR++;
                            $r--;
                        }
                        $pairs += $cntL * $cntR;
                    }
                }
            }

            $total += $pairs * $freq;
        }

        return $total;
    }
}
