class Solution {

    /**
     * @param Integer[] $nums
     * @param Integer $k
     * @return Boolean
     */
    function canPartitionKSubsets($nums, $k) {
        $totalSum = array_sum($nums);
        if ($totalSum % $k !== 0) {
            return false;
        }

        $target = intdiv($totalSum, $k);
        rsort($nums);

        if ($nums[0] > $target) {
            return false;
        }

        $n = count($nums);
        $numStates = 1 << $n;
        $dp = array_fill(0, $numStates, -1);
        $dp[0] = 0;

        for ($mask = 0; $mask < $numStates; $mask++) {
            if ($dp[$mask] === -1) {
                continue;
            }

            for ($i = 0; $i < $n; $i++) {
                if (!($mask & (1 << $i))) {
                    if ($dp[$mask] + $nums[$i] <= $target) {
                        $nextMask = $mask | (1 << $i);
                        $dp[$nextMask] = ($dp[$mask] + $nums[$i]) % $target;
                    } else {
                        break;
                    }
                }
            }
        }

        return $dp[$numStates - 1] === 0;
    }
}
