class Solution {

    /**
     * @param Integer[] $slices
     * @return Integer
     */
    function maxSizeSlices($slices) {
        $n = count($slices) / 3;
        $case1 = array_slice($slices, 0, count($slices) - 1);
        $case2 = array_slice($slices, 1);

        return max($this->linearMax($case1, $n), $this->linearMax($case2, $n));
    }

    private function linearMax($arr, $k) {
        $m = count($arr);
        $dp = array_fill(0, $m + 1, array_fill(0, $k + 1, 0));

        for ($i = 1; $i <= $m; $i++) {
            for ($j = 1; $j <= $k; $j++) {
                $take = ($i >= 2 ? $dp[$i - 2][$j - 1] : 0) + $arr[$i - 1];
                $notTake = $dp[$i - 1][$j];
                $dp[$i][$j] = max($take, $notTake);
            }
        }

        return $dp[$m][$k];
    }
}
