class Solution {

    /**
     * @param Integer $n
     * @param Integer[][] $restrictions
     * @param Integer[][] $requests
     * @return Boolean[]
     */
    function friendRequests($n, $restrictions, $requests) {
        $parent = range(0, $n - 1);

        $find = function ($i) use (&$parent, &$find) {
            if ($parent[$i] !== $i) {
                $parent[$i] = $find($parent[$i]);
            }
            return $parent[$i];
        };

        $ans = [];

        foreach ($requests as $req) {
            $ru = $find($req[0]);
            $rv = $find($req[1]);

            if ($ru === $rv) {
                $ans[] = true;
                continue;
            }

            $valid = true;
            foreach ($restrictions as $res) {
                $rx = $find($res[0]);
                $ry = $find($res[1]);

                if (($rx === $ru && $ry === $rv) || ($rx === $rv && $ry === $ru)) {
                    $valid = false;
                    break;
                }
            }

            if ($valid) {
                $parent[$ru] = $rv;
                $ans[] = true;
            } else {
                $ans[] = false;
            }
        }

        return $ans;
    }
}
