class Solution {

    /**
     * @param String[] $grid
     * @return Integer
     */
    function regionsBySlashes($grid) {
        $n = count($grid);
        $m = $n * 3;
        $g = array_fill(0, $m, array_fill(0, $m, 0));

        for ($i = 0; $i < $n; $i++) {
            for ($j = 0; $j < $n; $j++) {
                $c = $grid[$i][$j];
                if ($c === '/') {
                    $g[$i * 3][$j * 3 + 2] = 1;
                    $g[$i * 3 + 1][$j * 3 + 1] = 1;
                    $g[$i * 3 + 2][$j * 3] = 1;
                } elseif ($c === '\\') {
                    $g[$i * 3][$j * 3] = 1;
                    $g[$i * 3 + 1][$j * 3 + 1] = 1;
                    $g[$i * 3 + 2][$j * 3 + 2] = 1;
                }
            }
        }

        $regions = 0;
        $dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];

        for ($i = 0; $i < $m; $i++) {
            for ($j = 0; $j < $m; $j++) {
                if ($g[$i][$j] === 0) {
                    $regions++;
                    $queue = [[$i, $j]];
                    $g[$i][$j] = 1;
                    $head = 0;
                    while ($head < count($queue)) {
                        [$r, $c] = $queue[$head++];
                        foreach ($dirs as [$dr, $dc]) {
                            $nr = $r + $dr;
                            $nc = $c + $dc;
                            if ($nr >= 0 && $nr < $m && $nc >= 0 && $nc < $m && $g[$nr][$nc] === 0) {
                                $g[$nr][$nc] = 1;
                                $queue[] = [$nr, $nc];
                            }
                        }
                    }
                }
            }
        }

        return $regions;
    }
}
