class Solution {

    /**
     * @param String $s
     * @return String[]
     */
    function removeInvalidParentheses($s) {
        $res = [];
        $queue = [$s];
        $visited = [$s => true];
        $found = false;

        while (!empty($queue)) {
            $nextQueue = [];
            foreach ($queue as $str) {
                if ($this->isValid($str)) {
                    $res[] = $str;
                    $found = true;
                }

                if ($found) {
                    continue;
                }

                $len = strlen($str);
                for ($i = 0; $i < $len; $i++) {
                    if ($str[$i] !== '(' && $str[$i] !== ')') {
                        continue;
                    }
                    $sub = substr($str, 0, $i) . substr($str, $i + 1);
                    if (!isset($visited[$sub])) {
                        $visited[$sub] = true;
                        $nextQueue[] = $sub;
                    }
                }
            }

            if ($found) {
                break;
            }
            $queue = $nextQueue;
        }

        return empty($res) ? [""] : $res;
    }

    private function isValid($str) {
        $count = 0;
        $len = strlen($str);
        for ($i = 0; $i < $len; $i++) {
            $c = $str[$i];
            if ($c === '(') {
                $count++;
            } elseif ($c === ')') {
                $count--;
                if ($count < 0) {
                    return false;
                }
            }
        }
        return $count === 0;
    }
}
