        }

        $n = count($adjacentPairs) + 1;
        $ans = [];
        $curr = $start;
        $prev = null;

        for ($i = 0; $i < $n; $i++) {
            $ans[] = $curr;
            $next = null;
            foreach ($adj[$curr] as $neighbor) {
                if ($neighbor !== $prev) {
                    $next = $neighbor;
                    break;
                }
            }
            $prev = $curr;
            $curr = $next;
        }

        return $ans;
    }
