    function shiftGrid($grid, $k) {
        $m = count($grid);
        $n = count($grid[0]);
        $total = $m * $n;
        $k = $k % $total;

        $result = array_fill(0, $m, array_fill(0, $n, 0));

        for ($i = 0; $i < $m; $i++) {
            for ($j = 0; $j < $n; $j++) {
                $idx = $i * $n + $j;
                $origIdx = ($idx - $k + $total) % $total;
                $origI = intdiv($origIdx, $n);
                $origJ = $origIdx % $n;
                $result[$i][$j] = $grid[$origI][$origJ];
            }
        }

        return $result;
    }
