class Solution {

    /**
     * @param Integer $rows
     * @param Integer $cols
     * @param Integer $rStart
     * @param Integer $cStart
     * @return Integer[][]
     */
    function spiralMatrixIII($rows, $cols, $rStart, $cStart) {
        $res = [[$rStart, $cStart]];
        $total = $rows * $cols;
        if ($total == 1) {
            return $res;
        }

        $dr = [0, 1, 0, -1];
        $dc = [1, 0, -1, 0];
        $dir = 0;
        $steps = 1;

        $r = $rStart;
        $c = $cStart;

        while (count($res) < $total) {
            for ($i = 0; $i < 2; $i++) {
                for ($s = 0; $s < $steps; $s++) {
                    $r += $dr[$dir];
                    $c += $dc[$dir];

                    if ($r >= 0 && $r < $rows && $c >= 0 && $c < $cols) {
                        $res[] = [$r, $c];
                        if (count($res) == $total) {
                            return $res;
                        }
                    }
                }
                $dir = ($dir + 1) % 4;
            }
            $steps++;
        }

        return $res;
    }
}
