class Solution {

    /**
     * @param Integer[] $nums
     * @param Integer $k
     * @return Integer
     */
    function splitArray($nums, $k) {
        $low = 0;
        $high = 0;

        foreach ($nums as $num) {
            if ($num > $low) {
                $low = $num;
            }
            $high += $num;
        }

        while ($low < $high) {
            $mid = $low + intdiv($high - $low, 2);

            $count = 1;
            $currentSum = 0;
            foreach ($nums as $num) {
                if ($currentSum + $num > $mid) {
                    $count++;
                    $currentSum = $num;
                } else {
                    $currentSum += $num;
                }
            }

            if ($count <= $k) {
                $high = $mid;
            } else {
                $low = $mid + 1;
            }
        }

        return $low;
    }
}
