class Solution {

    /**
     * @param String[] $stickers
     * @param String $target
     * @return Integer
     */
    function minStickers($stickers, $target) {
        $m = strlen($target);
        $num_stickers = count($stickers);

        // Count characters for each sticker
        $sticker_counts = [];
        foreach ($stickers as $sticker) {
            $cnt = array_fill(0, 26, 0);
            $len = strlen($sticker);
            for ($i = 0; $i < $len; $i++) {
                $cnt[ord($sticker[$i]) - 97]++;
            }
            $sticker_counts[] = $cnt;
        }

        $memo = array_fill(0, 1 << $m, -1);
        $memo[(1 << $m) - 1] = 0;

        $dfs = function($mask) use (&$dfs, &$memo, $sticker_counts, $target, $m) {
            if ($memo[$mask] !== -1) {
                return $memo[$mask];
            }

            // Find the first unset bit
            $first_unset = 0;
            for ($i = 0; $i < $m; $i++) {
                if (!(($mask >> $i) & 1)) {
                    $first_unset = $i;
                    break;
                }
            }

            $target_char_code = ord($target[$first_unset]) - 97;
            $res = 1000000000;

            foreach ($sticker_counts as $cnt) {
                // Pruning: only consider stickers containing target[first_unset]
                if ($cnt[$target_char_code] === 0) {
                    continue;
                }

                $available = $cnt;
                $new_mask = $mask;
                for ($i = 0; $i < $m; $i++) {
                    if (!(($new_mask >> $i) & 1)) {
                        $c = ord($target[$i]) - 97;
                        if ($available[$c] > 0) {
                            $available[$c]--;
                            $new_mask |= (1 << $i);
                        }
                    }
                }

                $sub = $dfs($new_mask);
                if ($sub !== 1000000000) {
                    $res = min($res, 1 + $sub);
                }
            }

            $memo[$mask] = $res;
            return $res;
        };

        $ans = $dfs(0);
        return $ans >= 1000000000 ? -1 : $ans;
    }
}
