    private $stream = '';
    private $maxLen = 0;

    /**
     * @param String[] $words
     */
    function __construct($words) {
        foreach ($words as $word) {
            $len = strlen($word);
            if ($len > $this->maxLen) {
                $this->maxLen = $len;
            }
            $curr = &$this->trie;
            for ($i = $len - 1; $i >= 0; $i--) {
                $ch = $word[$i];
                if (!isset($curr[$ch])) {
                    $curr[$ch] = [];
                }
                $curr = &$curr[$ch];
            }
            $curr['#'] = true;
            unset($curr);
        }
    }

    /**
     * @param String $letter
     * @return Boolean
     */
    function query($letter) {
        $this->stream .= $letter;
        if (strlen($this->stream) > $this->maxLen) {
            $this->stream = substr($this->stream, 1);
        }

        $curr = &$this->trie;
        for ($i = strlen($this->stream) - 1; $i >= 0; $i--) {
            $ch = $this->stream[$i];
            if (!isset($curr[$ch])) {
                return false;
            }
            $curr = &$curr[$ch];
            if (isset($curr['#'])) {
                return true;
            }
        }

        return false;
    }
}

