```php
class Solution {

    private $memo = [];

    /**
     * @param Integer $n
     * @param Integer $firstPlayer
     * @param Integer $secondPlayer
     * @return Integer[]
     */
    function earliestAndLatest($n, $firstPlayer, $secondPlayer) {
        $key = "$n,$firstPlayer,$secondPlayer";
        if (isset($this->memo[$key])) {
            return $this->memo[$key];
        }

        // If they compete against each other in this round
        if ($firstPlayer + $secondPlayer === $n + 1) {
            return [1, 1];
        }

        $pairs = [];
        $half = intdiv($n, 2);

        for ($i = 1; $i <= $half; $i++) {
            $j = $n - $i + 1;
            if ($i === $firstPlayer || $j === $firstPlayer) {
                // firstPlayer must win
                $pairs[] = [[(int)($firstPlayer < $firstPlayer), (int)($firstPlayer < $secondPlayer)]];
            } elseif ($i === $secondPlayer || $j === $secondPlayer) {
                // secondPlayer must win
                $pairs[] = [[(int)($secondPlayer < $firstPlayer), (int)($secondPlayer < $secondPlayer)]];
            } else {
                // Either i or j wins
                $opt1 = [(int)($i < $firstPlayer), (int)($i < $secondPlayer)];
                $opt2 = [(int)($j < $firstPlayer), (int)($j < $secondPlayer)];
                if ($opt1 === $opt2) {
                    $pairs[] = [$opt1];
                } else {
                    $pairs[] = [$opt1, $opt2];
                }
            }
        }

        // If n is odd, the middle player advances automatically
        if ($n % 2 === 1) {
            $mid = intdiv($n + 1, 2);
            $pairs[] = [[(int)($mid < $firstPlayer), (int)($mid < $secondPlayer)]];
        }

        // Find all reachable (count_f, count_s)
        $reachable = [0 => [0 => true]];
        foreach ($pairs as $options) {
            $nextReachable = [];
            foreach ($reachable as $cf => $sfList) {
                foreach ($sfList as $cs => $_) {
                    foreach ($options as [$addF, $addS]) {
                        $nextReachable[$cf + $addF][$cs + $addS] = true;
                    }
                }
            }
            $reachable = $nextReachable;
        }

        $nextN = intdiv($n + 1, 2);
        $minR = PHP_INT_MAX;
        $maxR = PHP_INT_MIN;

        foreach ($reachable as $cf => $sfList) {
            foreach ($sfList as $cs => $_) {
                $nextF = 1 + $cf;
                $nextS = 1 + $cs;
                [$r1, $r2] = $this->earliestAndLatest($nextN, $nextF, $nextS);
                $minR = min($minR, 1 + $r1);
                $maxR = max($maxR, 1 + $r2);
            }
        }

        return $this->memo[$key] = [$minR, $maxR];
    }
}
