class Solution {

    /**
     * @param Integer[] $nums
     * @param Integer[][] $edges
     * @return Integer[]
     */
    function getCoprimes($nums, $edges) {
        $n = count($nums);

        // Precompute coprimes for 1..50
        $coprimes = [];
        for ($i = 1; $i <= 50; $i++) {
            $coprimes[$i] = [];
            for ($j = 1; $j <= 50; $j++) {
                $a = $i;
                $b = $j;
                while ($b != 0) {
                    $t = $b;
                    $b = $a % $b;
                    $a = $t;
                }
                if ($a == 1) {
                    $coprimes[$i][] = $j;
                }
            }
        }

        // Build adjacency list
        $adj = array_fill(0, $n, []);
        foreach ($edges as $edge) {
            $u = $edge[0];
            $v = $edge[1];
            $adj[$u][] = $v;
            $adj[$v][] = $u;
        }

        $ans = array_fill(0, $n, -1);
        $val_stacks = array_fill(1, 50, []);

        // Iterative DFS: [$u, $parent, $depth, $stage]
        // stage 0: enter, stage 1: exit
        $stack = [[0, -1, 0, 0]];

        while (!empty($stack)) {
            $item = array_pop($stack);
            $u = $item[0];
            $p = $item[1];
            $depth = $item[2];
            $stage = $item[3];

            if ($stage == 0) {
                $val = $nums[$u];
                $best_depth = -1;
                $best_node = -1;

                foreach ($coprimes[$val] as $c) {
                    if (!empty($val_stacks[$c])) {
                        $top = $val_stacks[$c][count($val_stacks[$c]) - 1];
                        if ($top[1] > $best_depth) {
                            $best_depth = $top[1];
                            $best_node = $top[0];
                        }
                    }
                }

                $ans[$u] = $best_node;
                $val_stacks[$val][] = [$u, $depth];

                // Push exit stage for current node
                $stack[] = [$u, $p, $depth, 1];

                // Push children
                foreach ($adj[$u] as $v) {
                    if ($v != $p) {
                        $stack[] = [$v, $u, $depth + 1, 0];
                    }
                }
            } else {
                array_pop($val_stacks[$nums[$u]]);
            }
        }

        return $ans;
    }
}
