class Solution {

    /**
     * @param Integer $n
     * @param Integer[] $leftChild
     * @param Integer[] $rightChild
     * @return Boolean
     */
    function validateBinaryTreeNodes($n, $leftChild, $rightChild) {
        $inDegree = array_fill(0, $n, 0);

        for ($i = 0; $i < $n; $i++) {
            if ($leftChild[$i] !== -1) {
                $inDegree[$leftChild[$i]]++;
                if ($inDegree[$leftChild[$i]] > 1) {
                    return false;
                }
            }
            if ($rightChild[$i] !== -1) {
                $inDegree[$rightChild[$i]]++;
                if ($inDegree[$rightChild[$i]] > 1) {
                    return false;
                }
            }
        }

        $root = -1;
        for ($i = 0; $i < $n; $i++) {
            if ($inDegree[$i] === 0) {
                if ($root !== -1) {
                    return false;
                }
                $root = $i;
            }
        }

        if ($root === -1) {
            return false;
        }

        $visited = array_fill(0, $n, false);
        $queue = [$root];
        $visited[$root] = true;
        $count = 0;

        $head = 0;
        while ($head < count($queue)) {
            $curr = $queue[$head++];
            $count++;

            $left = $leftChild[$curr];
            if ($left !== -1) {
                if ($visited[$left]) {
                    return false;
                }
                $visited[$left] = true;
                $queue[] = $left;
            }

            $right = $rightChild[$curr];
            if ($right !== -1) {
                if ($visited[$right]) {
                    return false;
                }
                $visited[$right] = true;
                $queue[] = $right;
            }
        }

        return $count === $n;
    }
}
