class Solution {

    private $words_ids;
    private $w_lens;
    private $res_ids;
    private $res_len;
    private $num_words;
    private $assigned;
    private $used;
    private $cannot_be_zero;

    /**
     * @param String[] $words
     * @param String $result
     * @return Boolean
     */
    function isSolvable($words, $result) {
        $this->res_len = strlen($result);
        $max_word_len = 0;
        foreach ($words as $w) {
            $len = strlen($w);
            if ($len > $this->res_len) {
                return false;
            }
            if ($len > $max_word_len) {
                $max_word_len = $len;
            }
        }

        if ($this->res_len > $max_word_len + 1) {
            return false;
        }

        $char_map = [];
        $char_count = 0;
        $cannot_be_zero_chars = [];

        foreach ($words as $w) {
            $len = strlen($w);
            if ($len > 1) {
                $cannot_be_zero_chars[$w[0]] = true;
            }
            for ($i = 0; $i < $len; $i++) {
                $c = $w[$i];
                if (!isset($char_map[$c])) {
                    $char_map[$c] = $char_count++;
                }
            }
        }

        if ($this->res_len > 1) {
            $cannot_be_zero_chars[$result[0]] = true;
        }
        for ($i = 0; $i < $this->res_len; $i++) {
            $c = $result[$i];
            if (!isset($char_map[$c])) {
                $char_map[$c] = $char_count++;
            }
        }

        if ($char_count > 10) {
            return false;
        }

        $this->cannot_be_zero = array_fill(0, $char_count, false);
        foreach ($cannot_be_zero_chars as $c => $val) {
            $this->cannot_be_zero[$char_map[$c]] = true;
        }

        $this->num_words = count($words);
        $this->words_ids = [];
        $this->w_lens = [];
        foreach ($words as $w) {
            $len = strlen($w);
            $this->w_lens[] = $len;
            $ids = [];
            for ($i = $len - 1; $i >= 0; $i--) {
                $ids[] = $char_map[$w[$i]];
            }
            $this->words_ids[] = $ids;
        }

        $this->res_ids = [];
        for ($i = $this->res_len - 1; $i >= 0; $i--) {
            $this->res_ids[] = $char_map[$result[$i]];
        }

        $this->assigned = array_fill(0, $char_count, -1);
        $this->used = array_fill(0, 10, false);

        return $this->search(0, 0, 0);
    }

    private function search($col, $word_idx, $carry) {
        if ($col === $this->res_len) {
            return $carry === 0;
        }

        if ($word_idx < $this->num_words) {
            if ($col >= $this->w_lens[$word_idx]) {
                return $this->search($col, $word_idx + 1, $carry);
            }

            $char_id = $this->words_ids[$word_idx][$col];
            if ($this->assigned[$char_id] !== -1) {
                return $this->search($col, $word_idx + 1, $carry + $this->assigned[$char_id]);
            }

            $start = $this->cannot_be_zero[$char_id] ? 1 : 0;
            for ($d = $start; $d <= 9; $d++) {
                if (!$this->used[$d]) {
                    $this->used[$d] = true;
                    $this->assigned[$char_id] = $d;
                    if ($this->search($col, $word_idx + 1, $carry + $d)) {
                        return true;
                    }
                    $this->assigned[$char_id] = -1;
                    $this->used[$d] = false;
                }
            }
            return false;
        }

        $char_id = $this->res_ids[$col];
        $target = $carry % 10;
        $next_carry = intdiv($carry, 10);

        if ($this->assigned[$char_id] !== -1) {
            if ($this->assigned[$char_id] === $target) {
                return $this->search($col + 1, 0, $next_carry);
            }
            return false;
        }

        if ($target === 0 && $this->cannot_be_zero[$char_id]) {
            return false;
        }
        if ($this->used[$target]) {
            return false;
        }

        $this->used[$target] = true;
        $this->assigned[$char_id] = $target;
        if ($this->search($col + 1, 0, $next_carry)) {
            return true;
        }
        $this->assigned[$char_id] = -1;
        $this->used[$target] = false;

        return false;
    }
}
