    function isMatch($s, $p) {
        $sLen = strlen($s);
        $pLen = strlen($p);

        $sIdx = 0;
        $pIdx = 0;
        $starIdx = -1;
        $sTmpIdx = -1;

        while ($sIdx < $sLen) {
            if ($pIdx < $pLen && ($p[$pIdx] === '?' || $p[$pIdx] === $s[$sIdx])) {
                $sIdx++;
                $pIdx++;
            } elseif ($pIdx < $pLen && $p[$pIdx] === '*') {
                $starIdx = $pIdx;
                $sTmpIdx = $sIdx;
                $pIdx++;
            } elseif ($starIdx !== -1) {
                $pIdx = $starIdx + 1;
                $sTmpIdx++;
                $sIdx = $sTmpIdx;
            } else {
                return false;
            }
        }

