class Solution {

    /**
     * @param String $beginWord
     * @param String $endWord
     * @param String[] $wordList
     * @return Integer
     */
    function ladderLength($beginWord, $endWord, $wordList) {
        $wordSet = array_flip($wordList);
        if (!isset($wordSet[$endWord])) {
            return 0;
        }

        $beginSet = [$beginWord => true];
        $endSet = [$endWord => true];
        unset($wordSet[$beginWord], $wordSet[$endWord]);

        $len = strlen($beginWord);
        $dist = 1;

        while (!empty($beginSet) && !empty($endSet)) {
            if (count($beginSet) > count($endSet)) {
                $temp = $beginSet;
                $beginSet = $endSet;
                $endSet = $temp;
            }

            $nextSet = [];
            foreach ($beginSet as $word => $_) {
                for ($i = 0; $i < $len; $i++) {
                    $originalChar = $word[$i];
                    for ($c = 97; $c <= 122; $c++) {
                        $char = chr($c);
                        if ($char === $originalChar) {
                            continue;
                        }
                        $word[$i] = $char;

                        if (isset($endSet[$word])) {
                            return $dist + 1;
                        }

                        if (isset($wordSet[$word])) {
                            $nextSet[$word] = true;
                            unset($wordSet[$word]);
                        }
                    }
                    $word[$i] = $originalChar;
                }
            }

            $beginSet = $nextSet;
            $dist++;
        }

        return 0;
    }
}
